package ru.domeguard; import org.bukkit.command.*;import org.bukkit.entity.Player; public final class DomeCommand implements CommandExecutor{private final DomeManager dome;private final DomeMenu menu;public DomeCommand(DomeManager d,DomeMenu m){dome=d;menu=m;}public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p)){s.sendMessage("Only players can use /dome.");return true;}if(!p.hasPermission("dome.admin")){p.sendMessage("Нет прав.");return true;}menu.open(p);return true;}}
